// =============================================================================
// module name：crc16_generate
// author: OpenHappy Team
// MAS：spec/link_layer/submods/link_tx/mas/crc16_generate_mas.md
// 功能概述: 性能模式 TX 侧 256 B Flit 的 CRC16 生成单元。单引擎 1008 bit
//           计算 / 16 bit 输出（输入端口 1024 bit，对齐完整单元），CRC0 与 CRC1 由父
//           模块分时复用同一引擎（前 128 B 收齐拍送 Byte 0~127 采 CRC0；后 128 B
//           收齐拍送 Byte 128~255（含更新后 DLP）采 CRC1）。输入单元 16bit
//           校验码槽位 [1023:1008] 不被矩阵引用（1008 bit 口径，调用方可送完整
//           单元，槽位值不影响输出）。多项式
//           x^16 + x^15 + x^2 + 1（16'h8005，Init=0xFFFF，无输入/输出反转，
//           XorOut=0x0000）。本模块为纯组合逻辑，输入数据稳定后输出同拍
//           有效，无寄存器延迟；不做模式判断 / valid 门控 / 引擎使能门控 /
//           注错处理（均由父模块 link_tx 处理）。
// =============================================================================
// version history(仅记录规格变更、重要BUG修复，不记录lint等小问题修改)
//   <日期>  <修订人>  <变更概述>
//  2026-08-06  OpenHappy Team  初始版本
//  2026-08-06  OpenHappy Team  function 迭代写法改为并行 XOR 矩阵展开逐 bit 赋值，
//                          功能不变（与 Galois 迭代对拍一致）
//  2026-08-07  OpenHappy Team  删除 DATA_W 参数：展开矩阵按 1024 bit 固化，参数化无意义
//  2026-09-23  OpenHappy Team  契约自包含：槽位 [1023:1008] 内部清零（矩阵输入改名 crc16_kern_w）；
//                          与调用方预清零逐位等价、功能零变化
//  2026-09-23  OpenHappy Team  用户裁决（LL-20260923-CHK1008）：CRC16 校验码改按
//                          1008 bits 计算（覆盖 crc16_data_i[1007:0] = 单元 Byte 0~125），
//                          废弃"槽位 [1023:1008] 补 0 后按 1024 bits 计算"旧口径（含
//                          v1.5 内部清零 crc16_kern_w 表述）；矩阵改 1008-bit 符号展开——
//                          结构性不引用槽位（非"引用但清零"）；信源 analysis/gen_crc16_matrix.py
//                          （产物 analysis/crc16_matrix_verilog.txt：16 条 assign、7350 数据项
//                          + 常量 0xd558〔置位 bit 15/14/12/10/8/6/4/3〕，仅引用 [1007:0]，
//                          勿手改）；校验码值随口径变化（d=0: 0x7fdf→0xd558，旧口径废弃），
//                          TX/RX 共用同一新矩阵 → 链路自洽；纯组合 0 cycle 属性不变
// =============================================================================

`timescale 1ns/1ps

module crc16_generate (

    // 数据输入（1024 bit 对齐：128 B 数据单元，分时承载 Byte 0~127 / Byte 128~255；
    // 计算口径 1008 bits——矩阵仅引用 [1007:0]，槽位 [1023:1008] 不被矩阵引用，调用方可送完整单元）
    input  wire [1023:0]      crc16_data_i,

    // 数据输出
    output wire [15:0]        crc16_o
);

// =============================================================================
// 组合逻辑：并行 CRC16 XOR 矩阵展开（无 function / 无 for 循环，逐 bit 直接赋值）
// -----------------------------------------------------------------------------
// 由 Galois LFSR（poly=16'h8005, Init=16'hffff, 1008 步迭代）符号展开生成
// （1008-bit 口径：矩阵结构性不引用槽位 [1023:1008]，调用方可送完整单元，槽位值
// 不改变输出）；crc16_o[b] = 对应输入 bit 与常量项的 XOR（常量 0xd558 来自非零
// init——置位 bit 15/14/12/10/8/6/4/3），综合后即为 16 棵 XOR 树。
// 信源 analysis/gen_crc16_matrix.py（产物 analysis/crc16_matrix_verilog.txt），勿手改。
// =============================================================================


// crc16_o[15] : 590 项 XOR
assign crc16_o[15] =
        crc16_data_i[1006] ^ crc16_data_i[1005] ^ crc16_data_i[1004] ^ crc16_data_i[1002] ^ crc16_data_i[1000] ^ crc16_data_i[998] ^
